WITH scored AS (SELECT *, NTILE(5) OVER (PARTITION BY dept_name ORDER BY budget DESC, id) AS budget_bucket, PERCENT_RANK() OVER w_running AS budget_percent_rank, NTILE(4) OVER w_part AS budget_bucket_2 FROM departments WINDOW w_running AS (PARTITION BY location, dept_name ORDER BY budget NULLS FIRST), w_part AS (PARTITION BY location ORDER BY budget DESC, id)) SELECT location, CASE WHEN budget_bucket_2 >= 7 THEN 'HIGH' ELSE 'LOW' END AS budget_bucket_2_tier, COUNT(CASE WHEN dept_name = 'HR' THEN 1 END) AS hr_count, COUNT(DISTINCT id) AS distinct_ids, ROUND(AVG(budget_percent_rank), 2) AS avg_budget_percent_rank, PERCENTILE_APPROX(budget_percent_rank, 0.5) AS budget_percent_rank_p50, COUNT(DISTINCT dept_name) AS distinct_dept_names, COUNT(DISTINCT id) AS distinct_ids_2 FROM scored GROUP BY location, budget_bucket_2_tier HAVING COUNT(DISTINCT id) > 1 ORDER BY budget_bucket_2_tier DESC NULLS LAST
